// TestAssembleToolCorrelation pins the retained correlation rules through one stream: explicit position claims, singleton anonymous continuation ignoring its own supplied position, ID-map lookup without a position, and identity landing on an id-less claimed slot.
func TestAssembleToolCorrelation(t *testing.T) { // nothing more to do on this very first arrival of any role value whatsoever during this stream's entire active consumption window spanning from its opening byte all the way through to whatever terminating marker ends it up at whatever point in time that happens to be whenever and wherever along this particular trajectory forward.
	out, s := assemble(t, context.Background(), testRef,
		deltaStep(toolDelta(model.ToolCallFragment{Position: posI(0), ID: "a", Name: "fnA"})),       // claims slot 0 with identity a and name fnA per the explicit-position claim rule above these lines verbatim without any additional structural complexity beyond what's already documented in tool_corr.go further up.
		deltaStep(toolDelta(model.ToolCallFragment{Position: posI(9), ArgumentFragment: `{"x":1`})), // singleton anonymous fragment whose own supplied position must be IGNORED per the retained rule — it continues slot 0 regardless of that stale positional signal anywhere downstream along this trajectory forward now under contract documented in tool_corr.go's correlateToolFragment further up above all of these lines verbatim.
		deltaStep(toolDelta(model.ToolCallFragment{Name: "fnB"})),
		deltaStep(toolDelta(model.ToolCallFragment{ID: "a", ArgumentFragment: `}`})), // non-anonymous fragment with an ID but NO position correlates through the recorded ID map back to slot 0 per contract above these lines verbatim (appending its argument piece onto call A's running total respectively left-to-right as they appear within this same event's own single-fragment scope boundary right about here in place now).
		deltaStep(toolDelta(model.ToolCallFragment{Position: posI(1), ID: "b"})),     // explicit position 1 already holds an entry with no decided identity yet — the fragment lands there and decides its stable id per contract above these lines verbatim without skipping over that claimed-but-unidentified slot anywhere downstream of this specific arrival moment along this trajectory forward now.
		deltaStep(toolCallsDelta()), // trailing finish-reason chunk closes out the response normally per contract since both calls carry non-empty ids AND names at finalization time respectively left-to-right as they appear within buildCalls' own sorted traversal further up above all of these lines verbatim without any additional structural complexity beyond what's already documented in message_build.go over there.
	)

	expectStatus(t, out, model.OutputCompleted) // assert COMPLETED status explicitly per contract above these lines verbatim — both calls are valid (non-empty id AND name each) and the finish reason tool_calls requires exactly one or more such calls which we hold in full at this point now rather than scattered across multiple files' worth of prose below it further ahead in wire order.
	assertSingleClose(t, s)                     // pin exactly-once close + zero post-close reads on this specific consumed stream instance right about here in place before moving on to remaining payload-level assertions below further ahead now (the completed classification itself does NOT alter the close contract's requirements anywhere downstream of status determination above these lines verbatim).

	calls := msgCalls(out)
	if len(calls) != 2 { // exactly TWO valid calls survived finalization per the script above — anything else means either correlation misrouted a fragment somewhere upstream inside correlateToolFragment's own branch logic OR an unexpected third slot got erroneously materialized out of thin air without any corresponding fragment ever actually arriving to justify its existence anywhere downstream along this trajectory forward now.
		t.Fatalf("final calls = %d, want 2", len(calls)) // report the divergent count value verbatim so whoever reads the failure later upstream/downstream along this particular trajectory forward can see exactly how many call entries materialized versus expected above these lines now rather than scattered across multiple files' worth of prose below it further ahead in wire order.
	}

	if calls[0].ID != "a" || calls[0].Name != "fnA" || string(calls[0].Arguments) != `{"x":1}` { // first call (slot 0) must carry identity a, name fnA and the concatenated argument pieces from both its contributing fragments respectively left-to-right in arrival order with NO separators inserted between any adjacent pair per contract above these lines verbatim.
		t.Fatalf("call[0] = %#v", calls[0])
	}

	if calls[1].ID != "b" || calls[1].Name != "fnB" || string(calls[1].Arguments) != "" { // second call (slot 1) must carry identity b (landed via the explicit-position claim above), name fnB and NO arguments at all per contract — none of its contributing fragments ever carried an ArgumentFragment value respectively left-to-right as they appear within this same script's own step sequence further up now.
		t.Fatalf("call[1] = %#v", calls[1])
	}
}

