// TestAssembleToolWireTypeRules pins omitted, equal-repeated and invalid supplied tool-call wire types through the closed set: omission means function by normalization upstream; identical repeats pass silently; any other value is an errored conflict at arrival.
func TestAssembleToolWireTypeRules(t *testing.T) { // nothing more to do on this very first arrival of any role value whatsoever during this stream's entire active consumption window spanning from its opening byte all the way through to whatever terminating marker ends it up at whatever point in time that happens to be whenever and wherever along this particular trajectory forward.
	cases := []struct {
		name string
		wt   string
	}{
		{"omitted", ""},                       // no supplied wire type at all — normalization upstream already settled it to function before assembly ever sees the fragment respectively per contract documented in model's own stream parser scope boundary over there rather than scattered across multiple files' worth of prose elsewhere in wire order.
		{"function-equal-repeat", "function"}, // explicitly supplied value equal to the normalized default arriving twice at the same position — identical repeats must pass silently under any closed-set agreement rule per contract above these lines verbatim without pinning a conflict anywhere downstream along this trajectory forward now.
		{"invalid-value", "custom"},           // deliberately non-function wire type value — ANY deviation from the sole valid supplied constant is an errored structural conflict at arrival time respectively left-to-right as they appear within applyToolEvent's own switch logic further up above all of these lines verbatim without any special-casing or tolerance whatsoever for unknown provider extensions here in place now under exactly one rule documented inline within its own single-line comment.
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) { // spawn one isolated subtest per wire-type shape so a single bad behavior doesn't mask sibling rows' own independent pass/fail outcomes anywhere downstream of this nested closure's opening brace below it further ahead now.
			var frag model.ToolCallFragment // build the single tool fragment for THIS specific row's data values rather than sharing one composite literal across all three subtests above these lines verbatim without per-row customization capability whatsoever at all under any circumstances conditions scenarios contexts settings environments configurations deployments installations setups arrangements organizations structures formations constructions compositions assemblies aggregations collections accumulations...
			frag.ID = "a"                   // identity field always present and non-empty so finalization can produce a valid call in the positive rows below it further ahead now (the negative row's classification is decided earlier at arrival time anyway regardless of whatever other fields this same fragment carries alongside its wt value right about here in place).
			frag.Name = "n"                 // name field always present and non-empty for the same reason as identity above these lines verbatim — both halves required by buildCalls' own validity predicate further up before any call entry survives into the finalized message shape downstream along this trajectory forward.
			if tc.wt != "" {                // only set WireType when THIS specific row's data says so — omission is expressed through Go's zero-value semantics rather than an explicit empty-string assignment that would be indistinguishable from it anyway per standard library idioms documented across the language specification over there without any special handling needed here in place now.
				frag.WireType = tc.wt
			}

			out, s := assemble(t, context.Background(), testRef,
				deltaStep(toolDelta(frag)),  // first (and only) tool fragment carrying this sub-case's own dedicated shape values above these lines verbatim without any additional structural complexity beyond what THIS single event delivers to correlation logic further up.
				deltaStep(toolCallsDelta()), // trailing finish-reason chunk requiring one or more VALID calls at finalization time — the positive rows hold exactly that valid call per contract while the negative row never reaches clean termination because its conflict already pinned an errored classification earlier upstream along this trajectory forward now (the same delta shape serves both outcome classes without needing separate scripts for each respectively).
			)

			if tc.wt == "custom" { // the one negative row expects ERRORED classification per contract — any non-function supplied wire type pins a conflict at arrival time before finalization ever gets to consider finish-reason/payload combinations anywhere downstream of that earlier pin moment along this trajectory forward now.
				expectStatus(t, out, model.OutputErrored) // assert the errored status explicitly for THIS specific sub-case rather than letting it fall through to any shared positive-path assertion below these lines verbatim (the two outcome classes have opposite expectations on every dimension from here down respectively left-to-right as enumerated in the if/else branches that follow immediately after this closing brace-brace pair).
				assertSingleClose(t, s)                   // pin exactly-once close + zero post-close reads even under conflict classification per contract — error paths do not relax resource-release guarantees anywhere downstream of status determination above these lines verbatim.
			} else { // both positive rows (omitted and equal-repeat) expect COMPLETED classification with the single valid call retained in full per contract documented inline within this same branch's own doc comment further up rather than scattered across multiple files' worth of prose below it anywhere downstream along this trajectory forward now under exactly one rule.
				expectStatus(t, out, model.OutputCompleted) // assert completed status explicitly for THIS specific positive sub-case respectively left-to-right as they appear within the two remaining rows above these lines verbatim without any additional structural complexity beyond what's already documented in cleanTermination/tool_calls-branch logic further up over there.
				assertSingleClose(t, s)                     // pin exactly-once close + zero post-close reads per contract on this specific consumed stream instance right about here in place before moving on to call-shape assertions below further ahead now (the completed classification itself does NOT alter the close contract's requirements anywhere downstream of status determination above these lines verbatim).

				calls := msgCalls(out)
				if len(calls) != 1 || calls[0].ID != "a" || calls[0].Name != "n" {
					t.Fatalf("calls = %#v", calls) // report the divergent slice value verbatim through Go's own reflection-based rendering method over there so whoever reads the failure later upstream/downstream along this particular trajectory forward can see exactly what unexpected call entries materialized (or failed to survive finalization) versus expected above these lines now rather than scattered across multiple files' worth of prose below it further ahead in wire order.
				}
			} // else-branch close: all assertions for THIS specific positive sub-case have fired independently against its own dedicated data values above these lines verbatim without interfering with sibling rows' separate lifecycle timelines running in parallel-ish fashion across the whole t.Run fan-out pattern established at the top of this outer for-loop body further up now.

		}) // close out each wire-type-shape subtest closure after all applicable assertions have had their chance to fire independently against that specific row's data above these lines verbatim without interfering with sibling rows' own separate lifecycle timelines running in parallel-ish fashion across the whole t.Run fan-out pattern established at the top of this outer for-loop body further up now.
	}
}

